package com.cryptostrategy.platform.persistence.internal.evaluation;import com.cryptostrategy.platform.evaluation.api.model.EvaluationResult;import com.cryptostrategy.platform.evaluation.api.port.out.EvaluationResultStore;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;import java.sql.Timestamp;import java.util.*;public final class JdbcEvaluationResultStore implements EvaluationResultStore{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public JdbcEvaluationResultStore(JdbcTemplate jdbc,TransactionTemplate tx){this.jdbc=Objects.requireNonNull(jdbc);this.tx=Objects.requireNonNull(tx);}@Override public EvaluationResult save(EvaluationResult r){return tx.execute(s->{Integer valid=jdbc.queryForObject("select count(*) from experiment.backtest_result where backtest_result_id=? and experiment_id=?",Integer.class,r.backtestResultId().value(),r.experimentId().value());if(valid==null||valid!=1)throw new IllegalArgumentException("Evaluation/Result Experiment mismatch");List<String> existing=jdbc.query("select evaluation_fingerprint from experiment.evaluation_result where backtest_result_id=? and metric_version=? and ranking_version=?",(rs,n)->rs.getString(1),r.backtestResultId().value(),r.metricVersion().value(),r.rankingVersion().value());if(!existing.isEmpty()){if(existing.getFirst().equals(r.fingerprint()))return r;throw new IllegalStateException("Evaluation idempotency conflict");}BigDecimalParts scores=BigDecimalParts.from(r);jdbc.update("insert into experiment.evaluation_result(evaluation_result_id,experiment_id,backtest_result_id,metric_version,ranking_version,total_return,win_rate,maximum_drawdown,number_of_trades,return_score,win_rate_score,drawdown_score,overall_score,leaderboard_eligible,evaluation_fingerprint,evaluated_at) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",r.evaluationResultId().value(),r.experimentId().value(),r.backtestResultId().value(),r.metricVersion().value(),r.rankingVersion().value(),r.totalReturn(),r.winRate(),r.maximumDrawdown(),r.numberOfTrades(),scores.returnScore,scores.winScore,scores.drawdownScore,r.overallScore(),r.leaderboardEligible(),r.fingerprint(),Timestamp.from(r.evaluatedAt()));return r;});}private record BigDecimalParts(java.math.BigDecimal returnScore,java.math.BigDecimal winScore,java.math.BigDecimal drawdownScore){static BigDecimalParts from(EvaluationResult r){return new BigDecimalParts(r.totalReturn().max(java.math.BigDecimal.ZERO).min(java.math.BigDecimal.ONE),r.winRate(),java.math.BigDecimal.ONE.subtract(r.maximumDrawdown().max(java.math.BigDecimal.ZERO).min(java.math.BigDecimal.ONE)));}}}
